import json

L = 80.0
B = 13.0
CB = 0.70
fr = 1.0

# Ref [8] says requirement applies to ships with length above 90 m.
# Here L = 80 m, which is not above 90 m.
if L <= 90:
    print("REFUSE: Ship length must be above 90 m for minimum midship moment of inertia requirement according to Pt.3 Ch.5 Sec.2 [1.5.1]")
else:
    # Formula from [8]
    if L < 90:
        Cw = 0.0856 * L
    elif L <= 300:
        Cw = 10.75 - ((300 - L) / 100)**1.5
    elif L <= 350:
        Cw = 10.75
    else:
        Cw = 10.75 - ((L - 350) / 150)**1.5

    Iy_R_gr = 3 * fr * Cw * (L**3) * B * (CB + 0.7) * (10**-8)

    print(json.dumps({
        "value": Iy_R_gr,
        "unit": "m4",
        "clause": "DNV-RU-SHIP Pt.3 Ch.5 Sec.2 [1.5.2]"
    }))
